// Precompiles each schema in VALIDATORS into a standalone ES module.
// Workers forbid new Function, so Ajv cannot compile at runtime there. The page and the
// Worker both import the same generated file, so there is exactly one validator per schema.
//
// Run with `pnpm build:validators`. The output is committed, and a test checks that
// regenerating it gives byte-identical output.

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";

const root = fileURLToPath(new URL("..", import.meta.url));

export const VALIDATORS = [
  {
    schemaPath: "schemas/interaction-report.schema.json",
    outputPath: "public/generated/validate-interaction-report.js",
    exportName: "validateInteractionReport"
  },
  {
    schemaPath: "schemas/fingerprint-stability.schema.json",
    outputPath: "public/generated/validate-fingerprint-stability.js",
    exportName: "validateFingerprintStability"
  }
];

export const VALIDATOR_SCHEMA_PATH = VALIDATORS[0].schemaPath;
export const VALIDATOR_OUTPUT_PATH = VALIDATORS[0].outputPath;

export function buildValidatorSource(repoRoot = root, validator = VALIDATORS[0]) {
  const schema = JSON.parse(readFileSync(join(repoRoot, validator.schemaPath), "utf8"));
  const ajv = new Ajv2020({ code: { source: true, esm: true, lines: true }, allErrors: true });
  ajv.compile(schema);
  const body = standaloneCode(ajv, { [validator.exportName]: schema.$id });
  return `// Generated by scripts/build-validators.mjs from ${validator.schemaPath}. Do not edit.\n${body}\n`;
}

if (import.meta.url === pathToFileURL(process.argv[1] || "").href) {
  for (const validator of VALIDATORS) {
    writeFileSync(join(root, validator.outputPath), buildValidatorSource(root, validator));
    console.log(`wrote ${validator.outputPath}`);
  }
}
